CREATE FUNCTION reject_environmental_native_source_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Environmental native source is append-only'; END $$;
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_source_versions FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_scenarios FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_configuration FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_variables FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_objectives FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_rewards_raw FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_challenge_groups FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_group_members FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();
CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON environmental_native_protector_groups FOR EACH ROW EXECUTE FUNCTION reject_environmental_native_source_mutation();

-- Original bhO -> bhF -> bhS -> bhR display consumers. Never grants rewards.
CREATE VIEW environmental_native_reward_display AS
WITH ordered AS (
 SELECT r.*,count(*) OVER(PARTITION BY source_key,scenario_id,native_flag,field_ahh) AS order_population,
 row_number() OVER(PARTITION BY source_key,scenario_id,native_flag ORDER BY field_ahh) AS display_position
 FROM environmental_native_rewards_raw r
)
SELECT source_key,scenario_id,reward_id,field_aai AS item_reference,field_ahj AS item_quantity,
 field_ago AS base_xp,field_ahk AS kamas,field_ahh AS display_order,
 native_flag AS primary_reward_list,
 CASE WHEN native_flag AND order_population=1 THEN display_position-1 ELSE NULL END AS primary_result_index,
 false AS server_grant_authorized
FROM ordered;
